def build(pre, ino):
    if not pre: return None
    r = pre[0]; i = ino.index(r)
    return (r, build(pre[1:1+i], ino[:i]), build(pre[1+i:], ino[i+1:]))
def post(t): return [] if t is None else post(t[1]) + post(t[2]) + [t[0]]
def find(t, x):
    if t is None: return None
    return t if t[0] == x else (find(t[1], x) or find(t[2], x))
def nodes(t): return set() if t is None else {t[0]} | nodes(t[1]) | nodes(t[2])
